/* VCD dumping functions */
MOD_mkFp32MulCoreTestbench & mkFp32MulCoreTestbench_backing(tSimStateHdl simHdl)
{
  static MOD_mkFp32MulCoreTestbench *instance = NULL;
  if (instance == NULL)
  {
    vcd_set_backing_instance(simHdl, true);
    instance = new MOD_mkFp32MulCoreTestbench(simHdl, "top", NULL);
    vcd_set_backing_instance(simHdl, false);
  }
  return *instance;
}
void MODEL_mkFp32MulCoreTestbench::dump_VCD_defs()
{
  (mkFp32MulCoreTestbench_instance->dump_VCD_defs)(vcd_depth(sim_hdl));
}
void MODEL_mkFp32MulCoreTestbench::dump_VCD(tVCDDumpType dt)
{
  (mkFp32MulCoreTestbench_instance->dump_VCD)(dt,
					      vcd_depth(sim_hdl),
					      mkFp32MulCoreTestbench_backing(sim_hdl));
}
